import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;
import java.util.TreeSet;

public class Div2_421C_Variant5 {

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer(br.readLine());
		int a = Integer.parseInt(st.nextToken());
		int b = Integer.parseInt(st.nextToken());
		long l = Long.parseLong(st.nextToken());
		long r = Long.parseLong(st.nextToken());

		if (r - l + 1 >= 2 * (a + b)) {
			System.out.println(a <= b ? a + 1 : 2 * a - b);
			return;
		}

		StringBuilder patternBuilder = new StringBuilder();
		for (int i = 0; i < a; i++) {
			patternBuilder.append((char) ('a' + i));
		}

		l--;
		r--;

		TreeSet<Integer> usedCharsSet = new TreeSet<>();
		int minDistinctChars = 26;

		for (int startIdx = 0; startIdx < 26; startIdx++) {
			for (int secondIdx = a; secondIdx < 26; secondIdx++) {
				StringBuilder currentStr = new StringBuilder(patternBuilder);
				for (int i = 0; i < b; i++) {
					currentStr.append((char) ('a' + startIdx));
				}
				usedCharsSet.clear();
				for (char c : currentStr.substring(currentStr.length() - a).toString().toCharArray()) {
					usedCharsSet.add(c - 'a');
				}
				int nextCharCode = 0;
				for (int i = 0; i < a; i++) {
					while (usedCharsSet.contains(nextCharCode)) {
						nextCharCode++;
					}
					currentStr.append((char) ('a' + nextCharCode));
					nextCharCode++;
				}
				for (int i = 0; i < b; i++) {
					currentStr.append((char) ('a' + secondIdx));
				}
				int totalLen = currentStr.length();
				usedCharsSet.clear();
				for (int i = (int) (l % totalLen); i != (r + 1) % totalLen; i = (i + 1) % totalLen) {
					usedCharsSet.add(currentStr.charAt(i) - 'a');
				}
				if (usedCharsSet.size() < minDistinctChars) {
					minDistinctChars = usedCharsSet.size();
				}
			}
		}
		System.out.println(minDistinctChars);
	}
}
